"""Pixel sprites from assets/sprites/sprites.json (palette + rows, generated by tools/sprites/mobs.py).

Surfaces are built once and cached per (name, size, flipped, white flash). Missing sprites
return None, so the renderer can fall back to coloured shapes.
"""

from __future__ import annotations

import json
from pathlib import Path

import pygame


def _find_assets_dir() -> Path:
    """`assets/` next to `src/` in the repo, or next to the `lastbean` package in the web build."""
    here = Path(__file__).resolve()
    for base in (here.parents[3], here.parents[2]):
        if (base / "assets" / "sprites" / "sprites.json").is_file():
            return base / "assets"
    return here.parents[3] / "assets"


ASSETS_DIR = _find_assets_dir()


def _hex(c: str) -> tuple[int, int, int]:
    c = c.lstrip("#")
    return int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)


class SpriteBank:
    def __init__(self, path: Path | None = None) -> None:
        path = path or ASSETS_DIR / "sprites" / "sprites.json"
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            raw = {}
        self._base: dict[str, pygame.Surface] = {name: self._build(s) for name, s in raw.items()}
        self._cache: dict[tuple, pygame.Surface] = {}

    @staticmethod
    def _build(s: dict) -> pygame.Surface:
        surf = pygame.Surface((s["w"], s["h"]), pygame.SRCALPHA)
        pal = {k: _hex(v) for k, v in s["pal"].items()}
        for y, row in enumerate(s["rows"]):
            for x, ch in enumerate(row):
                if ch != ".":
                    surf.set_at((x, y), (*pal[ch], 255))
        return surf

    def __contains__(self, name: str) -> bool:
        return name in self._base

    def get(
        self, name: str, scale: float = 1.0, flip: bool = False, flash: bool = False, squash: int = 0
    ) -> pygame.Surface | None:
        """Sprite `name`, scaled by `scale` (nearest neighbour), mirrored, or as a white silhouette.

        `squash` animates: -1 wide and flat (landing, hit), 1 narrow and tall (stepping up), 0 as drawn.
        """
        base = self._base.get(name)
        if base is None:
            return None
        key = (name, round(scale, 2), flip, flash, squash)
        surf = self._cache.get(key)
        if surf is None:
            surf = base
            w, h = base.get_size()
            w, h = max(1, round(w * scale)), max(1, round(h * scale))
            if squash:
                d = max(1, h // 10)
                w, h = (w + 2 * d, h - d) if squash < 0 else (w - d, h + d)
            if (w, h) != base.get_size():
                surf = pygame.transform.scale(base, (w, h))
            if flip:
                surf = pygame.transform.flip(surf, True, False)
            if flash:
                surf = surf.copy()
                surf.fill((255, 255, 255, 0), special_flags=pygame.BLEND_RGBA_MAX)
            self._cache[key] = surf
        return surf
